<?php global $product; if ( ! $product || ! is_a( $product, 'WC_Product' ) ) { $product = wc_get_product( get_the_ID() ); } if ( ! $product ) { return; } ?><article <?php wc_product_class( 'product-card', $product ); ?>><div class="product-media"><a href="<?php echo esc_url( $product->get_permalink() ); ?>"><?php souqify_product_badges( $product ); echo wp_kses_post( $product->get_image( 'souqify-product-card', array( 'loading' => 'lazy' ) ) ); ?></a><button type="button" class="wishlist-button" aria-label="<?php esc_attr_e( 'Add to wishlist', 'souqify' ); ?>"><?php souqify_svg_icon( 'heart' ); ?></button><button type="button" class="quick-view-button" data-product-id="<?php echo esc_attr( $product->get_id() ); ?>"><?php esc_html_e( 'Quick view', 'souqify' ); ?></button></div><div class="product-card-body"><h3 class="product-title"><a href="<?php echo esc_url( $product->get_permalink() ); ?>"><?php echo esc_html( $product->get_name() ); ?></a></h3><div class="product-rating"><?php echo wp_kses_post( wc_get_rating_html( $product->get_average_rating(), $product->get_rating_count() ) ); ?><span>(<?php echo esc_html( $product->get_rating_count() ); ?>)</span></div><div class="product-price"><?php echo wp_kses_post( $product->get_price_html() ); ?></div><?php souqify_stock_indicator( $product ); ?><a href="<?php echo esc_url( $product->add_to_cart_url() ); ?>" data-quantity="1" data-product_id="<?php echo esc_attr( $product->get_id() ); ?>" class="button add_to_cart_button ajax_add_to_cart"><?php esc_html_e( 'Add to cart', 'souqify' ); ?></a></div></article>
